import{b as i,O as t,g as a,j as e}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"并行执行与性能","description":"","frontmatter":{},"headers":[],"relativePath":"automation/pytest/advanced/parallel-performance/index.md","filePath":"自动化测试/2.pytest+requests/5.进阶篇/29.并行与性能.md","lastUpdated":1786983642000}'),n={name:"automation/pytest/advanced/parallel-performance/index.md"};function l(d,s,h,p,o,k){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="并行执行与性能" tabindex="-1">并行执行与性能 <a class="header-anchor" href="#并行执行与性能" aria-label="Permalink to &quot;并行执行与性能&quot;">​</a></h1><blockquote><p>接口测试套件几百个用例，串行跑要十几分钟，等不起。这一章讲 pytest 的提速三板斧：先「止损」（快速失败）、再「聚焦」（只跑相关的）、最后「并行」（多进程同时跑）。</p></blockquote><h2 id="三板斧之一-快速失败-x" tabindex="-1">三板斧之一：快速失败 -x <a class="header-anchor" href="#三板斧之一-快速失败-x" aria-label="Permalink to &quot;三板斧之一：快速失败 -x&quot;">​</a></h2><p>发现第一个失败就停，别让后面 500 个用例陪跑：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 第一个失败立即停</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --maxfail=3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 失败 3 个才停（容错一些）</span></span></code></pre></div><p>适合「改完代码快速验证有没有搞坏」的场景——失败立即知道，不用等全套跑完。</p><h2 id="三板斧之二-聚焦-lf-k" tabindex="-1">三板斧之二：聚焦 --lf / -k <a class="header-anchor" href="#三板斧之二-聚焦-lf-k" aria-label="Permalink to &quot;三板斧之二：聚焦 --lf / -k&quot;">​</a></h2><p>只跑「上次失败的」或「指定的」：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lf</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 只跑上次失败的用例（--last-failed）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 先跑上次失败的，再跑其余（--failed-first）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;login or cart&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 只跑名字匹配的用例</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 只跑冒烟标记的用例（第 25 章）</span></span></code></pre></div><blockquote><p><strong>要点：<code>--lf</code> 是接口测试最常用的加速手段——改完一处 bug，只重跑刚才失败的用例验证，几秒出结果。它靠 <code>.pytest_cache/</code> 记录上次失败状态，<code>--cache-clear</code> 可清空。</strong></p></blockquote><h2 id="三板斧之三-并行-pytest-xdist" tabindex="-1">三板斧之三：并行 pytest-xdist <a class="header-anchor" href="#三板斧之三-并行-pytest-xdist" aria-label="Permalink to &quot;三板斧之三：并行 pytest-xdist&quot;">​</a></h2><p><code>pytest-xdist</code> 用多进程并行跑测试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest-xdist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 自动按 CPU 核数开进程</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 开 4 个进程</span></span></code></pre></div><p>原理：xdist 把测试分发给多个 worker 进程，每个进程跑一部分，跑完汇总。<strong>测试之间相互独立时，提速接近进程数倍。</strong></p><h3 id="分发模式-dist" tabindex="-1">分发模式 --dist <a class="header-anchor" href="#分发模式-dist" aria-label="Permalink to &quot;分发模式 --dist&quot;">​</a></h3><p><code>--dist</code> 控制怎么把测试分给 worker：</p><table tabindex="0"><thead><tr><th>模式</th><th>分发策略</th><th>适用场景</th></tr></thead><tbody><tr><td><code>load</code>（默认）</td><td>动态负载均衡，谁空谁拿</td><td>测试耗时差异大</td></tr><tr><td><code>loadscope</code></td><td>按「作用域」分组</td><td>同 fixture 的测试分给同一 worker</td></tr><tr><td><code>loadgroup</code></td><td>按 <code>xdist_group</code> 标记分组</td><td>手动指定哪些必须同组</td></tr><tr><td><code>loadfile</code></td><td>按文件分组</td><td>同一文件的测试给同一 worker</td></tr></tbody></table><h3 id="并行的坑-session-fixture-会复制" tabindex="-1">并行的坑：session fixture 会复制 <a class="header-anchor" href="#并行的坑-session-fixture-会复制" aria-label="Permalink to &quot;并行的坑：session fixture 会复制&quot;">​</a></h3><p>第 7 章讲过 session 级 fixture 整个会话共享一次。但<strong>并行时每个 worker 是独立进程，session fixture 会每个进程各执行一次</strong>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@pytest.fixture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">scope</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;session&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">():</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    api </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ApiClient(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BASE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    api.login(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ACCOUNTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;admin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># N 个 worker = 登录 N 次</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api</span></span></code></pre></div><p>大部分场景没问题（登录多几次无所谓）。但要注意：</p><ul><li><strong>不能有「全局唯一」的副作用</strong>：比如测试前重置数据库，每个 worker 都重置会互相干扰</li><li><strong>共享资源会冲突</strong>：多个 worker 同时写同一份文件、同一张表会打架</li></ul><blockquote><p><strong>要点：并行适合「每个测试独立、无共享状态」的接口测试（各测各的接口）。如果测试之间有数据依赖（测完 A 才能测 B），串行或按 <code>loadscope</code> 分组。</strong></p></blockquote><h2 id="提速手段总结" tabindex="-1">提速手段总结 <a class="header-anchor" href="#提速手段总结" aria-label="Permalink to &quot;提速手段总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>命令</th><th>何时用</th></tr></thead><tbody><tr><td>快速失败</td><td><code>-x</code> / <code>--maxfail</code></td><td>改完代码快速验证</td></tr><tr><td>聚焦</td><td><code>--lf</code> / <code>-k</code> / <code>-m</code></td><td>只重跑相关的</td></tr><tr><td>标记排除</td><td><code>-m &quot;not slow&quot;</code></td><td>日常排除慢测试</td></tr><tr><td>session 复用</td><td>fixture <code>scope=&quot;session&quot;</code></td><td>少重复登录/初始化</td></tr><tr><td>并行</td><td><code>-n auto</code></td><td>测试独立、量大时</td></tr></tbody></table><p><strong>组合拳</strong>（日常开发 + CI 两套配置）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 日常开发：快速反馈</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;not slow&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CI 完整跑：并行 + 报告</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --junitxml=reports/report.xml</span></span></code></pre></div><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ul><li>提速三板斧：<code>-x</code> 快速失败、<code>--lf</code>/<code>-k</code>/<code>-m</code> 聚焦、<code>-n</code> 并行</li><li><code>--lf</code> 只跑上次失败用例，是改完 bug 验证的最快方式</li><li><code>pytest-xdist</code> 多进程并行，<code>-n auto</code> 按核数开进程；测试独立时提速近 N 倍</li><li><code>--dist</code> 控制分发：<code>load</code>（默认）/<code>loadscope</code>/<code>loadgroup</code>/<code>loadfile</code></li><li>并行陷阱：session fixture 每 worker 各执行一次，共享资源会冲突，别做全局唯一副作用</li><li>日常用「<code>-x --lf -m not slow</code>」快速反馈，CI 用「<code>-n auto</code> + 报告」完整跑</li></ul>`,29)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
